import React, { useState, useEffect } from 'react';
import axios from 'axios';
import styled from 'styled-components';

const HomePage = () => {
  const [lorries, setLorries] = useState([]);
  const [showAddLorryForm, setShowAddLorryForm] = useState(false);
  const [newLorry, setNewLorry] = useState({
    registration_number: '',
    model: '',
    year_built: '',
    owner_phone: '',
  });
  const [error, setError] = useState('');
  const [role, setRole] = useState(''); // To check if the user is an owner

  // Fetch lorries when the component mounts
  useEffect(() => {
    const fetchLorries = async () => {
      try {
        const token = localStorage.getItem('token');
        const response = await axios.get('http://localhost:5001/api/lorry', {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        });
        setLorries(response.data);
      } catch (err) {
        console.error('Error fetching lorries:', err);
        setError('Error fetching lorries');
      }
    };

    fetchLorries();

    // Check if the logged-in user is an owner
    const user = JSON.parse(localStorage.getItem('user')); // Assuming user info is saved in localStorage
    if (user && user.role === 'owner') {
      setRole('owner');
    }

  }, []);

  // Handle form input change
  const handleInputChange = (e) => {
    setNewLorry({
      ...newLorry,
      [e.target.name]: e.target.value,
    });
  };

  // Handle form submission to add a new lorry
  const handleAddLorry = async (e) => {
    e.preventDefault();

    try {
      const token = localStorage.getItem('token');
      const response = await axios.post(
        'http://localhost:5001/api/lorry/add',
        newLorry,
        {
          headers: {
            Authorization: `Bearer ${token}`,
          },
        }
      );
      setLorries([...lorries, response.data.lorry]);
      setShowAddLorryForm(false); // Hide the form after submission
      setNewLorry({ registration_number: '', model: '', year_built: '', owner_phone: '' });
    } catch (err) {
      setError('Error adding lorry');
      console.error('Error:', err);
    }
  };

  return (
    <div>
      <h1>Lorries List</h1>
      {error && <p>{error}</p>}

      {role === 'owner' && (
        <button onClick={() => setShowAddLorryForm(!showAddLorryForm)}>
          {showAddLorryForm ? 'Cancel' : 'Add New Lorry'}
        </button>
      )}

      {showAddLorryForm && (
        <form onSubmit={handleAddLorry}>
          <input
            type="text"
            name="registration_number"
            value={newLorry.registration_number}
            onChange={handleInputChange}
            placeholder="Registration Number"
            required
          />
          <input
            type="text"
            name="model"
            value={newLorry.model}
            onChange={handleInputChange}
            placeholder="Model"
            required
          />
          <input
            type="number"
            name="year_built"
            value={newLorry.year_built}
            onChange={handleInputChange}
            placeholder="Year Built"
            required
          />
          <input
            type="text"
            name="owner_phone"
            value={newLorry.owner_phone}
            onChange={handleInputChange}
            placeholder="Owner Phone"
            required
          />
          <button type="submit">Add Lorry</button>
        </form>
      )}

      <div>
        <h2>Available Lorries</h2>
        {lorries.length > 0 ? (
          lorries.map((lorry) => (
            <div key={lorry.registration_number}>
              <p>{lorry.registration_number} - {lorry.model} - {lorry.year_built}</p>
            </div>
          ))
        ) : (
          <p>No lorries available</p>
        )}
      </div>
    </div>
  );
};

export default HomePage;


// Styled components

const Container = styled.div`
  display: flex;
  flex-direction: column;
  align-items: center;
  padding: 20px;
`;

const Header = styled.div`
  display: flex;
  justify-content: center;
  width: 100%;
  margin-bottom: 30px;
`;

const CompanyName = styled.h1`
  font-size: 3rem;
  font-weight: bold;
  color: #333;
`;

const AddLorryButton = styled.button`
  padding: 10px 20px;
  background-color: #4caf50;
  color: white;
  border: none;
  border-radius: 5px;
  cursor: pointer;
  margin-top: 20px;
`;

const AddLorryForm = styled.form`
  display: flex;
  flex-direction: column;
  gap: 10px;
  margin-top: 20px;
`;

const Input = styled.input`
  padding: 10px;
  font-size: 16px;
  border-radius: 5px;
  border: 1px solid #ddd;
`;

const LorryListContainer = styled.div`
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 20px;
`;

const LorryCard = styled.div`
  border: 1px solid #ddd;
  border-radius: 10px;
  padding: 15px;
  width: 300px;
  box-shadow: 0 4px 8px rgba(0, 0, 0, 0.1);
  margin: 20px;
  overflow: hidden;
  text-align: center;
  cursor: pointer;
  transition: 0.3s ease-in-out;

  &:hover {
    box-shadow: 0 6px 12px rgba(0, 0, 0, 0.2);
    transform: scale(1.05);
  }
`;

const ImageContainer = styled.div`
  height: 200px;
  width: 100%;
  overflow: hidden;
  border-radius: 10px;
  margin-bottom: 10px;

  img {
    width: 100%;
    height: 100%;
    object-fit: cover;
  }
`;

const OwnerName = styled.div`
  text-align: center;
  font-size: 1.2rem;
  font-weight: 500;
  margin-top: 10px;
  color: #333;
`;

const LorryDetails = styled.div`
  font-size: 14px;
  color: #333;

  div {
    margin: 5px 0;
  }
`;

const DeleteButton = styled.button`
  background-color: #f44336;
  color: white;
  border: none;
  padding: 5px 10px;
  border-radius: 5px;
  cursor: pointer;
  font-size: 14px;
  margin-top: 10px;

  &:hover {
    background-color: #e57373;
  }
`;
